problems.solution:
def relu(z):
    return max(0, z)

def tent(x):
    """Two ReLU neurons: 2x up to 1/2, then 2 - 2x."""
    return 2 * relu(x) - 4 * relu(x - 0.5)

def fold(x, k):
    """Apply the tent k times: a network k layers deep, 2 neurons wide."""
    for _ in range(k):
        x = tent(x)
    return x

def count_pieces(f, n=4096):
    ys = [f(i / n) for i in range(n + 1)]
    slopes = [(ys[i + 1] - ys[i]) * n for i in range(n)]
    changes = sum(1 for a, b in zip(slopes, slopes[1:]) if abs(a - b) > 1e-6)
    return changes + 1
